using System;using System.IO;using System.Text;using System.Collections.Generic;
namespace LordranEnemy {public static class DamageTests {
 static void Check(bool ok,string name){if(!ok)throw new Exception("Damage test failed: "+name);}
 static void Reject(Action action,string name){bool failed=false;try{action();}catch{failed=true;}Check(failed,name);}
 public static void Run(){long slot=0x10000,repo=0x20000,cap=0x30000,inner=0x40000,param=0x50000;var memory=new Dictionary<long,byte[]>();memory[slot]=BitConverter.GetBytes(repo);memory[repo+0x238]=BitConverter.GetBytes(cap);memory[cap+0x80]=BitConverter.GetBytes(inner);memory[inner+0x80]=BitConverter.GetBytes(param);memory[param-0x10]=BitConverter.GetBytes(4096);byte[] file=new byte[4096];Array.Copy(BitConverter.GetBytes((ushort)2),0,file,0xA,2);Array.Copy(BitConverter.GetBytes((long)0xE00),0,file,0x10,8);Array.Copy(Encoding.ASCII.GetBytes("NPC_PARAM_ST\0"),0,file,0xE00,13);Array.Copy(BitConverter.GetBytes(43114010),0,file,0x40,4);Array.Copy(BitConverter.GetBytes((long)0x100),0,file,0x48,8);Array.Copy(BitConverter.GetBytes(33500000),0,file,0x58,4);Array.Copy(BitConverter.GetBytes((long)0x800),0,file,0x60,8);float[] multipliers={1,.65f,1,1.1f,1,1.2f,.8f,1};for(int i=0;i<8;i++)Array.Copy(BitConverter.GetBytes(multipliers[i]),0,file,0x100+0x1A4+i*4,4);memory[param]=file;Func<long,int,byte[]> read=(a,n)=>{foreach(var region in memory){long offset=a-region.Key;if(offset>=0&&offset+n<=region.Value.Length){var bytes=new byte[n];Array.Copy(region.Value,(int)offset,bytes,0,n);return bytes;}}throw new Exception("Unmapped mock address.");};var damage=new NpcDamage();float[] values=damage.Read(slot,43114010,read);Check(Math.Abs(values[1]-35)<.001&&Math.Abs(values[5]+20)<.001&&values[0]==0,"Multiplier converts to positive, negative, neutral negation");Check(damage.Read(slot,43114010,read).Length==8,"Validated cached row");Reject(()=>damage.Read(slot,43114011,read),"Unknown exact NPC rejected");Array.Copy(BitConverter.GetBytes(float.NaN),0,file,0x100+0x1A4,4);Reject(()=>damage.Read(slot,43114010,read),"Non-finite data rejected");Array.Copy(BitConverter.GetBytes(1f),0,file,0x100+0x1A4,4);file[0xE00]=(byte)'X';Reject(()=>new NpcDamage().Read(slot,43114010,read),"Wrong parameter type rejected");file[0xE00]=(byte)'N';Array.Copy(BitConverter.GetBytes(43114010),0,file,0x58,4);Reject(()=>new NpcDamage().Read(slot,43114010,read),"Duplicate row IDs rejected");Array.Copy(BitConverter.GetBytes(33500000),0,file,0x58,4);Array.Copy(BitConverter.GetBytes((long)0x120),0,file,0x48,8);Reject(()=>damage.Read(slot,43114010,read),"Changed cached row rejected");Array.Copy(BitConverter.GetBytes((long)0x100),0,file,0x48,8);int reads=0;Reject(()=>new NpcDamage().Read(slot,43114010,(a,n)=>a==slot&&++reads==2?BitConverter.GetBytes(repo+0x100):read(a,n)),"Repository changes rejected");Array.Copy(BitConverter.GetBytes((long)0xF00),0,file,0x48,8);Reject(()=>new NpcDamage().Read(slot,43114010,read),"Out-of-bounds row rejected");Check(NpcDamage.Slots["2.7.1"]==0x3D85F58,"Reported game version has known repository slot");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"damage-test-results.txt"),"PASS: exact NPC row lookup, version slot, cached lookup, eight damage types, multiplier conversion, wrong type, missing row, duplicate IDs, non-finite values, changed row/repository, and out-of-bounds rejection. Mock memory only; live parameter access not tested.");}
}}
